// Gerado por scripts/build-pages.cjs a partir de scripts/data/months.cjs
window.MONTHS=[{"m":1,"e":"🍼","d":"O bebê passa a maior parte do tempo dormindo e mamando. Enxerga melhor a cerca de 20 a 30 cm, a distância do rosto de quem o segura, e reconhece vozes e cheiros familiares. Os movimentos ainda são reflexos, como o de sucção e o de preensão.","s":"1-mes"},{"m":2,"e":"😊","d":"Aparece o sorriso social, em resposta ao rosto e à voz de quem cuida. O bebê acompanha objetos com os olhos e, de bruços, levanta a cabeça por alguns instantes. Começa a fazer sons como “aaa” e “ooo”.","s":"2-meses"},{"m":3,"e":"👀","d":"O bebê sustenta melhor a cabeça, abre e fecha as mãos e as leva à boca. Observa as próprias mãos, sorri com frequência e pode começar a rir.","s":"3-meses"},{"m":4,"e":"🤲","d":"Sustenta a cabeça firme no colo, rola de bruços para o lado, ri alto e faz bolhas e barulhinhos. Agarra objetos e os leva à boca para explorar.","s":"4-meses"},{"m":5,"e":"🧸","d":"Rola de barriga para cima e para baixo, apoia-se nos antebraços de bruços e pode sentar com apoio. Reconhece o próprio nome e reage a emoções na voz.","s":"5-meses"},{"m":6,"e":"🥕","d":"Senta com pouco apoio, passa objetos de uma mão para a outra e balbucia sílabas. Pode estranhar pessoas desconhecidas.","s":"6-meses"},{"m":7,"e":"🪀","d":"Senta sem apoio por mais tempo, pode começar a se arrastar e procura objetos escondidos. Os primeiros dentes costumam aparecer nesta fase.","s":"7-meses"},{"m":8,"e":"🐛","d":"Muitos bebês engatinham ou se arrastam, e alguns tentam ficar de pé com apoio. Entendem “não” e brincam de esconde-esconde.","s":"8-meses"},{"m":9,"e":"👋","d":"Senta sem apoio, faz pinça com polegar e indicador, balbucia “mamama” e “papapa” e pode estranhar desconhecidos.","s":"9-meses"},{"m":10,"e":"🧱","d":"Fica de pé segurando nos móveis e pode dar passos laterais. Bate palmas, dá tchau e imita gestos.","s":"10-meses"},{"m":11,"e":"🎈","d":"Anda segurando nos móveis ou nas mãos de um adulto. Entende pedidos simples como “me dá” e aponta para o que quer.","s":"11-meses"},{"m":12,"e":"🎂","d":"Primeiro aniversário! Pode dar os primeiros passos sozinho, fala uma ou duas palavras com significado e entende muito mais do que consegue dizer.","s":"12-meses"},{"m":13,"e":"🚶","d":"Ganha confiança para andar, sobe em móveis baixos e explora tudo. Começa a usar objetos com função, como pentear o cabelo.","s":"13-meses"},{"m":14,"e":"🧩","d":"Aponta para pedir e mostrar coisas, imita palavras e tarefas de casa e encaixa formas simples.","s":"14-meses"},{"m":15,"e":"🎵","d":"Dá alguns passos sozinho, usa algumas palavras além de “mamã” e “papá” e segue ordens simples com gesto.","s":"15-meses"},{"m":16,"e":"🛝","d":"Anda com mais segurança, tenta correr e subir escadas engatinhando. Testa limites e quer fazer sozinha.","s":"16-meses"},{"m":17,"e":"🖍️","d":"Rabisca com giz, empilha blocos e reconhece partes do corpo quando nomeadas.","s":"17-meses"},{"m":18,"e":"🗣️","d":"Anda sem apoio, usa várias palavras, aponta para mostrar algo e brinca de faz de conta simples, como alimentar a boneca.","s":"18-meses"},{"m":19,"e":"🧺","d":"Ajuda em tarefas simples, como guardar brinquedos, e aumenta o vocabulário a cada semana.","s":"19-meses"},{"m":20,"e":"⚽","d":"Corre, chuta bola e sobe degraus com ajuda. Pode juntar duas palavras.","s":"20-meses"},{"m":21,"e":"📚","d":"Faz perguntas com gestos e palavras, identifica figuras em livros e imita adultos.","s":"21-meses"},{"m":22,"e":"🏃","d":"Corre com mais equilíbrio, sobe em brinquedos e começa a brincar perto de outras crianças.","s":"22-meses"},{"m":23,"e":"🎨","d":"Vocabulário em expansão, frases de duas palavras e mais autonomia para comer e se vestir.","s":"23-meses"},{"m":24,"e":"🥳","d":"Dois anos! Corre, chuta bola, junta duas ou mais palavras, aponta partes do corpo e brinca com mais de um brinquedo ao mesmo tempo.","s":"24-meses"}];
